def first_Factorial_Divisible_Number(x):
    """Return the smallest natural number n such that n! is divisible by x."""
    if not isinstance(x, int):
        raise TypeError("x must be an integer")
    if x < 1:
        raise ValueError("x must be a positive integer")
    if x == 1:
        return 1
    # Factorize x into primes: x = product p**a
    factors = {}
    remaining = x
    d = 2
    while d * d <= remaining:
        if remaining % d == 0:
            count = 0
            while remaining % d == 0:
                remaining //= d
                count += 1
            factors[d] = count
        d += 1 if d == 2 else 2
    if remaining > 1:
        factors[remaining] = 1

    def exponent_in_factorial(n, p):
        total = 0
        while n:
            n //= p
            total += n
        return total

    def min_n_for_prime_power(p, a):
        lo = 1
        hi = p * a
        while lo < hi:
            mid = (lo + hi) // 2
            if exponent_in_factorial(mid, p) >= a:
                hi = mid
            else:
                lo = mid + 1
        return lo

    return max(min_n_for_prime_power(p, a) for p, a in factors.items())
